import styled from "styled-components";

export const InputImageContainer = styled.div`
    width:4rem;
    height:4rem;
    display: flex;
    align-items: center;
    justify-content: center;

    input{
        font-size: 0.75rem;
        font-weight: 400;
        background: transparent;
        border: 0;
        width: 100%;
        height:100%;
        border: 1px dashed #000;
        
    }
`
